import numpy as np

def _pack_numeric(value):
    import numpy as np
    if isinstance(value, (tuple, list)):
        chunks = [np.array([2., float(len(value))])]
        for item in value:
            packed = _pack_numeric(item)
            chunks.extend((np.array([float(packed.size)]), packed))
        return np.concatenate(chunks)
    array = np.asarray(value, dtype=float)
    return np.concatenate((np.array([1., float(array.ndim)]),
